import fs from 'fs';
import path from 'path';

export const nestedFreshSessionWorkdirs = (projectPath: string): string[] => {
  const rivetDir = path.join(projectPath, '.rivet');
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(rivetDir, { withFileTypes: true });
  } catch {
    return [];
  }
  const workdirs: string[] = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const workdir = path.join(rivetDir, entry.name);
    const ownsHistory =
      fs.existsSync(path.join(workdir, '.rivet', 'variants')) ||
      fs.existsSync(path.join(workdir, '.rivet', 'store.git'));
    if (ownsHistory) workdirs.push(workdir);
  }
  return workdirs;
};
